export const localDate=(d=new Date())=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
export const birthday=name=>/\b(birthday|bday)\b/i.test(name);
export function occurrence(event,year){const [y,m,d]=event.date.split('-').map(Number);return localDate(new Date(birthday(event.name)?year:y,m-1,d));}
export function reminders(data,now=new Date()){
 const result=[];const add=(id,title,date)=>{if(date.getTime()>now.getTime())result.push({id,title,at:date.getTime()})};
 for(const t of data.tasks){if(t.done||!t.deadline)continue;const d=new Date(t.deadline+'T00:00:00');d.setDate(d.getDate()-1);add('task-'+t.id+'-'+t.deadline,'Due tomorrow: '+t.name,d)}
 for(const e of data.events){if(birthday(e.name)){for(let year=now.getFullYear();year<=now.getFullYear()+1;year++){const before=result.length;add('birthday-'+e.id+'-'+year,e.name,new Date(occurrence(e,year)+'T00:00:00'));if(result.length>before)Object.assign(result[result.length-1],{annualMonth:Number(e.date.slice(5,7)),annualDay:Number(e.date.slice(8,10))})}}else if(e.remind)add('event-'+e.id,e.name,new Date(e.date+'T'+(e.time||'00:00')+':00'))}return result;
}
export function totals(entries,month){return entries.filter(e=>e.date.startsWith(month)).reduce((a,e)=>{a[e.type==='revenue'?'revenue':'expenses']+=Number(e.amount);return a},{revenue:0,expenses:0})}
export function descendants(tasks,id){const found=new Set(),queue=[id];while(queue.length){const parent=queue.pop();for(const t of tasks)if(t.parent===parent&&t.id!==id&&!found.has(t.id)){found.add(t.id);queue.push(t.id)}}return found}
export function canMoveTask(tasks,id,parent){if(!tasks.some(t=>t.id===id))return false;if(!parent)return true;return parent!==id&&tasks.some(t=>t.id===parent)&&!descendants(tasks,id).has(parent)}
export function reopenAncestors(tasks,id){const seen=new Set();let t=tasks.find(t=>t.id===id);while(t?.parent&&!seen.has(t.parent)){seen.add(t.parent);t=tasks.find(x=>x.id===t.parent);if(t)t.done=false}}
export function moveTask(tasks,id,parent){if(!canMoveTask(tasks,id,parent))return false;const t=tasks.find(t=>t.id===id);t.parent=parent||null;if(!t.done)reopenAncestors(tasks,id);return true}
export function validTaskTree(tasks){const ids=new Set(tasks.map(t=>t.id));for(const t of tasks){const seen=new Set([t.id]);let parent=t.parent;while(parent){if(!ids.has(parent)||seen.has(parent))return false;seen.add(parent);parent=tasks.find(p=>p.id===parent)?.parent}}return true}
export function validateBackup(d){const date=s=>typeof s==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(s)&&localDate(new Date(s+'T12:00:00'))===s;const base=x=>x&&typeof x.id==='string'&&typeof x.name==='string'&&x.name.trim().length>0;return d&&d.version===1&&['tasks','entries','events'].every(k=>Array.isArray(d[k]))&&d.tasks.every(t=>base(t)&&typeof t.done==='boolean'&&Array.isArray(t.tags)&&t.tags.every(s=>typeof s==='string')&&(!t.deadline||date(t.deadline))&&(!t.parent||d.tasks.some(p=>p.id===t.parent&&!p.parent&&p.id!==t.id)))&&d.entries.every(e=>base(e)&&['revenue','game expenses','subscriptions','food'].includes(e.type)&&Number.isFinite(e.amount)&&e.amount>0&&date(e.date)&&(e.tags===undefined||(Array.isArray(e.tags)&&e.tags.every(t=>typeof t==='string'))))&&(!d.bankBalance||(Number.isFinite(d.bankBalance.amount)&&date(d.bankBalance.date)))&&d.events.every(e=>base(e)&&date(e.date)&&(!e.time||/^([01]\d|2[0-3]):[0-5]\d$/.test(e.time))&&typeof e.remind==='boolean')&&['tasks','entries','events'].every(k=>new Set(d[k].map(x=>x.id)).size===d[k].length)}

